"""Acceptance evidence for the six-window offline application shell."""
import base64,json,time,hashlib
def run(client,root,name):
 out=root/'tests/ui-overhaul-evidence';out.mkdir(exist_ok=True)
 client.navigate(root/'index.html')
 for _ in range(200):
  if client.evaluate('!!window.AL?.game&&!!AL.Shell'):break
  time.sleep(.05)
 checks=[]
 def ck(label,expr):
  try: checks.append({'name':label,'pass':bool(client.evaluate(expr))})
  except Exception as e: checks.append({'name':label,'pass':False,'error':str(e)})
 def runjs(js):client.evaluate('(()=>{'+js+'})()')
 def shot(label):
  data=client.call('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False});(out/f'{name}-{label}.png').write_bytes(base64.b64decode(data['data']))
 runjs("AL.Startup?.finish();AL.UI.close();AL.Store.close(false);AL.Shell.close(false);AL.game=AL.Core.newGame('marine',223);AL.game.settings.speed=0;AL.game.credits=100000;AL.game.level=11;AL.game.xp=2000;AL.game.stats.nightMarket=1;let t=AL.game.tanks[0];t.prepared=true;t.bacteria=t.bacteria2=1;AL.game=AL.Core.act(AL.game,'buyFish',{species:'clown',count:2});AL.UI.render();window.shellInitial=JSON.stringify(AL.game);")
 ck('Exactly six approved sidebar entries, in order',"JSON.stringify([...document.querySelectorAll('#navigation button')].map(b=>b.querySelector('.nav-text').textContent))===JSON.stringify(['Aquariums','Aquarium Store','Field Journal','Equipment','VIP Store','Settings'])")
 ck('VIP sidebar visibly labels Preview Only',"document.querySelector('[data-page=vip]').textContent.includes('Preview Only')")
 ck('Player-created first aquarium supports genuinely empty dry setup',"['fresh','marine'].every(route=>{const s=AL.Core.newGame(route,123,{empty:true}),t=s.tanks[0];AL.Save.validate(s);return t.emptyDry&&!t.prepared&&!t.equipment.length&&!t.fish.length&&!t.flora.length&&!t.decorations.length&&(route==='fresh'||!t.hardscape.length&&t.substrate.depth===0);})")
 for key in ['aquariums','store','journal','equipment','vip','settings']:
  runjs(f"document.querySelector('[data-page={key}]').click()")
  ck(f'{key}: dedicated titled modal with X',f"({'AL.Store.opened' if key=='store' else 'AL.Shell.opened&&AL.Shell.active==='+json.dumps(key)})&&document.querySelector('#{'store' if key=='store' else 'primary'}-close').getBoundingClientRect().width>0")
  ck(f'{key}: native keyboard modal focus',"document.activeElement.closest('dialog[open]')!==null")
  client.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Escape','code':'Escape'});client.call('Input.dispatchKeyEvent',{'type':'keyUp','key':'Escape','code':'Escape'})
  ck(f'{key}: Escape returns to visible aquarium',"!AL.Shell.opened&&!AL.Store.opened&&!document.getElementById('dialog').open&&document.getElementById('aquarium').getBoundingClientRect().height>0")
 ck('Opening and closing six windows preserves complete simulation state',"JSON.stringify(AL.game)===shellInitial")
 for w,h in [(1920,1080),(1440,900),(1366,768),(1280,720),(1024,600),(760,650),(390,844)]:
  client.call('Emulation.setDeviceMetricsOverride',{'width':w,'height':h,'deviceScaleFactor':1,'mobile':False});time.sleep(.15)
  ck(f'Viewport {w}x{h}: no page scrolling or horizontal overflow',"document.documentElement.scrollHeight<=innerHeight&&document.documentElement.scrollWidth<=innerWidth")
  ck(f'Viewport {w}x{h}: full canvas remains 2:1 inside viewport',"(()=>{const r=document.getElementById('aquarium').getBoundingClientRect();return Math.abs(r.width/r.height-2)<.02&&r.top>=0&&r.bottom<=innerHeight&&r.right<=innerWidth})()")
  ck(f'Viewport {w}x{h}: six sidebar controls remain visible',"[...document.querySelectorAll('#navigation button')].every(b=>{let r=b.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight})")
  shot(f'main-{w}-{h}')
 client.call('Emulation.setDeviceMetricsOverride',{'width':1440,'height':900,'deviceScaleFactor':1,'mobile':False});time.sleep(.15)
 ck('Value centered above water without obscuring scene',"(()=>{let v=document.getElementById('tank-value').getBoundingClientRect(),c=document.getElementById('aquarium').getBoundingClientRect();return Math.abs(v.x+v.width/2-c.x-c.width/2)<2&&v.bottom<=c.top})()")
 ck('Header uses real centralized selected-tank valuation',"document.getElementById('tank-value-amount').textContent===AL.Valuation.tank(AL.game,AL.Core.selected(AL.game)).total.toLocaleString('en-US')+' AC'")
 runjs("document.getElementById('tank-value').click()")
 ck('Click value opens Aquariums / Tank Value with complete breakdown',"AL.Shell.active==='aquariums'&&AL.Shell.subtab==='value'&&['Base tank value','Installed equipment','Fish & viable broods','Coral / plants','Bottom feeders','Rock, sand','Decorations','Total current asset value'].every(v=>document.getElementById('primary-content').textContent.includes(v))")
 shot('tank-value')
 runjs("AL.Shell.open('equipment','care');AL.Shell.open('journal','quests')")
 ck('Switching primary windows replaces cleanly',"document.querySelectorAll('dialog[open]').length===1&&AL.Shell.active==='journal'")
 runjs("AL.Shell.close();AL.Shell.open('journal')")
 ck('Window remembers its selected subtab',"AL.Shell.subtab==='quests'")
 runjs("AL.Shell.open('journal','encyclopedia')")
 ck('Journal includes fish, coral and plant notes with art',"[...document.querySelectorAll('[data-action=journalSpecies]')].every(n=>AL.Data.species[JSON.parse(n.dataset.args).id].water==='marine')&&document.querySelectorAll('[data-action=journalSpecies]').length>0")
 ck('Long modal contents have an internal scroll region',"document.getElementById('primary-content').scrollHeight>document.getElementById('primary-content').clientHeight&&getComputedStyle(document.getElementById('primary-content')).overflowY==='auto'")
 runjs("document.getElementById('primary-content').scrollTop=300")
 ck('Internal scrolling changes only modal content',"document.getElementById('primary-content').scrollTop===300&&window.scrollY===0")
 runjs("AL.Shell.notes('clown')")
 ck('Encyclopedia studies species without purchase form',"document.getElementById('dialog-body').textContent.includes('Amphiprion ocellaris')&&!document.getElementById('dialog-body').querySelector('[data-form=buyFish]')")
 runjs("AL.Startup?.finish();AL.UI.close();AL.Shell.open('journal','collection')")
 ck('Livestock Collection exposes all six requested filters',"document.querySelectorAll('[data-journal-filter]').length===6&&document.getElementById('primary-tabs').textContent.includes('Livestock Collection')")
 shot('journal-collection')
 runjs("AL.Shell.open('journal','disease')")
 ck('Disease guide references conditions without diagnosing a resident',"document.querySelectorAll('.guide-entry').length===12&&!document.getElementById('primary-content').textContent.includes('Examined:')")
 runjs("AL.Shell.open('equipment','care')")
 ck('Equipment has exactly Lighting, Tank Care and Water Change',"JSON.stringify([...document.querySelectorAll('#primary-tabs button')].map(b=>b.textContent))===JSON.stringify(['Lighting','Tank Care','Water Change'])")
 ck('Tank Care offers pumps, filters and heaters plus supported categories',"['Pumps','Filters','Heaters & Chillers','Protein Skimmers','Aeration'].every(v=>document.getElementById('primary-content').textContent.includes(v))")
