 ck('Lighting operates selected tank via existing transactions',"AL.Core.selected(AL.game).lightMode==='off'&&AL.Sim.light(AL.game,AL.Core.selected(AL.game))===0")
 shot('equipment-lighting')
 runjs("AL.Shell.open('equipment','care');document.querySelector('[data-action=uninstallEquipment][data-args*=heater]').click();")
 ck('Equipment removal retains the owned item in shared inventory',"!AL.Core.selected(AL.game).equipment.some(e=>e.type==='heater')&&AL.game.ownedEquipment.some(e=>e.type==='heater')")
 runjs("window.storedGear=JSON.stringify(AL.game.ownedEquipment);AL.game=AL.Save.parse(JSON.stringify(AL.game));")
 ck('Stored equipment identity and condition survive save/load',"JSON.stringify(AL.game.ownedEquipment)===storedGear")
 runjs("AL.UI.render();document.querySelector('[data-action=installOwnedEquipment]').click()")
 ck('Reinstallation uses the same owned equipment without purchasing a duplicate',"AL.Core.selected(AL.game).equipment.filter(e=>e.type==='heater').length===1&&AL.game.ownedEquipment.length===0")
 runjs("AL.Shell.open('vip')")
 ck('VIP five tiers and purchase prohibition remain intact',"['Bronze','Silver','Gold','Platinum','Diamond'].every(v=>document.getElementById('primary-content').textContent.includes(v))&&document.getElementById('primary-context').textContent.includes('NOT AVAILABLE FOR PURCHASE')&&AL.game.vip.paymentsEnabled===false")
 runjs("AL.Shell.open('store');AL.Store.open('fish','black')")
 ck('Store retains exactly three main tabs and Black Market',"JSON.stringify([...document.querySelectorAll('#store-main-tabs button')].map(b=>b.textContent))===JSON.stringify(['Saltwater','Freshwater','Black Market'])&&AL.Store.tab==='black'")
 runjs("document.querySelector('[data-store-mode=sell]').click()")
 ck('Marketplace selling exists inside store',"document.getElementById('store-products').textContent.includes('local exchange')&&document.getElementById('store-products').querySelector('[data-action=confirmSale]')!==null")
 runjs("document.querySelector('[data-store-mode=orders]').click()")
 ck('Store Orders shows actual delivered purchase history',"document.getElementById('store-products').textContent.includes('Ocellaris clownfish')")
 runjs("document.querySelector('[data-store-mode=buy]').click();AL.Store.open('flora','saltwater')")
 ck('Coral purchases remain in store',"AL.Store.products().filter(p=>p.kind==='flora').length===5")
 shot('store-corals')
 runjs("AL.Store.close(false);window.beforeTank=AL.game.selectedTank;AL.game=AL.Core.act(AL.game,'buyTank',{water:'marine',kind:'reef',volume:150,name:'Dry reef'});AL.UI.render();")
 ck('Purchased tank is empty and dry with no installed assets',"(()=>{const t=AL.Core.selected(AL.game);return t.emptyDry&&!t.prepared&&!t.equipment.length&&!t.fish.length&&!t.flora.length&&!t.hardscape.length&&!t.mounts.length&&t.substrate.depth===0})()")
 ck('Tank switch updates header value',"AL.game.selectedTank!==beforeTank&&document.getElementById('tank-value-amount').textContent===AL.Valuation.tank(AL.game,AL.Core.selected(AL.game)).total.toLocaleString('en-US')+' AC'")
 runjs("AL.Shell.open('equipment','change')")
 ck('Empty tank cannot perform normal water change',"document.querySelector('[data-action=waterChange]').disabled&&document.getElementById('primary-content').textContent.includes('empty and dry')")
 runjs("AL.Shell.close(false);AL.game.selectedTank=beforeTank;let t=AL.Core.selected(AL.game);AL.Sim.makeBrood(AL.game,t,'clown',t.fish[0],t.fish[1]);AL.Valuation.invalidate(AL.game);AL.UI.render();AL.renderer.zoom=1.5;AL.renderer.pan=.5;AL.renderer.draw(AL.game,0);window.broodId=t.eggs[0].id;window.broodAnchor=JSON.stringify(t.eggs[0].anchor);")
 ck('Marine clownfish clutch persists parent identities and rock anchoring',"(()=>{let e=AL.Core.selected(AL.game).eggs[0];return e.parents.length===2&&e.anchor.surface==='rock'&&e.id===broodId})()")
 ck('Eggs physically render and have selectable hitboxes in active tank',"AL.renderer.hitboxes.some(h=>h.id===broodId&&h.kind==='egg')")
 ck('Early-to-late egg artwork scale follows developmental progress',"(()=>{let e=AL.Core.selected(AL.game).eggs[0],early=AL.BroodView.size(e);return early===5&&AL.BroodView.size({...e,progress:e.required})===12&&!!AL.BroodView.image(e)&&!!AL.BroodView.image({...e,viability:0})})()")
 runjs("let e=AL.Core.selected(AL.game).eggs[0],t=AL.Core.selected(AL.game);window.clutchPosition=AL.BroodView.position(t,e);AL.renderer.draw(AL.game,1);AL.renderer.draw(AL.game,1);")
 ck('Eggs do not drift during scene animation',"JSON.stringify(AL.BroodView.position(AL.Core.selected(AL.game),AL.Core.selected(AL.game).eggs[0]))===JSON.stringify(clutchPosition)")
 runjs("window.originalTank=AL.game.selectedTank;AL.game.selectedTank=AL.game.tanks[1].id;AL.renderer.draw(AL.game,0);")
 ck('Clutch is rendered only in its own aquarium',"!AL.renderer.hitboxes.some(h=>h.id===broodId)")
 runjs("AL.game.selectedTank=originalTank;AL.renderer.draw(AL.game,0)")
 ck('Removing a spawning rock is blocked while its clutch is attached',"(()=>{let t=AL.Core.selected(AL.game),before=JSON.stringify(AL.game);try{AL.Core.act(AL.game,'removeRock',{id:t.eggs[0].anchor.supportId});return false;}catch{return JSON.stringify(AL.game)===before;}})()")
 runjs("let h=AL.renderer.hitboxes.find(h=>h.id===broodId),c=document.getElementById('aquarium'),r=c.getBoundingClientRect();c.dispatchEvent(new MouseEvent('click',{clientX:r.x+h.x*r.width,clientY:r.y+h.y*r.height,bubbles:true}));")
 ck('Actual egg click opens development inspector above aquarium',"document.getElementById('dialog').open&&document.getElementById('dialog-body').textContent.includes('Viability / clutch count')&&document.getElementById('egg-inspector')!==null")
 shot('egg-inspector')
 runjs("AL.Startup?.finish();AL.UI.close();AL.Shell.open('journal','breeding')")
 ck('Breeding records show parentage, incubation and growth',"['Clutches & parentage','Juvenile growth','suitable game hours'].every(v=>document.getElementById('primary-content').textContent.includes(v))")
 runjs("AL.Shell.close(false);AL.Core.selected(AL.game).eggs[0].progress=20;AL.UI.save();window.savedEgg=JSON.stringify(AL.Core.selected(AL.game).eggs[0]);AL.game=AL.Save.parse(JSON.stringify(AL.game));")
 ck('Egg progress, identity and anchoring survive save/load',"JSON.stringify(AL.Core.selected(AL.game).eggs[0])===savedEgg&&JSON.stringify(AL.Core.selected(AL.game).eggs[0].anchor)===broodAnchor")
 runjs("let t=AL.Core.selected(AL.game),e=t.eggs[0];window.clutchCount=e.count;window.preFish=t.fish.length;e.progress=e.required-.01;AL.Sim.step(AL.game,5);")
 ck('Egg-to-larva transition happens once with lineage',"!AL.Core.selected(AL.game).eggs.some(e=>e.id===broodId)&&AL.Core.selected(AL.game).fish.length===preFish+clutchCount&&AL.Core.selected(AL.game).fish.at(-1).growth<.3&&AL.Core.selected(AL.game).fish.at(-1).parents.length===2")
 runjs("window.afterHatch=AL.Core.selected(AL.game).fish.length;AL.game=AL.Save.parse(JSON.stringify(AL.game));AL.Sim.step(AL.game,5)")
 ck('Reload after hatch cannot duplicate offspring',"AL.Core.selected(AL.game).fish.length===afterHatch")
 runjs("AL.UI.render();AL.Shell.open('equipment','care');document.getElementById('primary-close').focus();")
 client.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Tab','code':'Tab','windowsVirtualKeyCode':9});client.call('Input.dispatchKeyEvent',{'type':'keyUp','key':'Tab','code':'Tab','windowsVirtualKeyCode':9})
 ck('Actual Tab key remains inside native modal focus trap',"document.activeElement.closest('#primary-dialog')!==null")
 runjs("window.selectedBeforeClick=AL.renderer.selected;document.getElementById('aquarium').dispatchEvent(new MouseEvent('click',{clientX:300,clientY:300,bubbles:true}));")
