 runjs("AL.Shell.close(false);let t=AL.Core.selected(AL.game);AL.Sim.makeBrood(AL.game,t,'clown',t.fish[0],t.fish[1]);let e=t.eggs.at(-1);e.viability=0;window.failedClutch=e.id;window.failedHatches=AL.game.stats.hatched;AL.Sim.step(AL.game,5);AL.renderer.draw(AL.game,0);AL.BroodView.inspect(e.id);")
 ck('Nonviable marine clutch remains visible with dead artwork and removal control',"AL.renderer.hitboxes.some(h=>h.id===failedClutch)&&document.getElementById('dialog-body').textContent.includes('Nonviable')&&document.querySelector('[data-action=removeBrood]')!==null")
 runjs("AL.game=AL.Save.parse(JSON.stringify(AL.game));AL.Sim.step(AL.game,5);document.querySelector('[data-action=removeBrood]').click();")
 ck('Removing a failed clutch cannot hatch or duplicate offspring after save/load',"!AL.Core.selected(AL.game).eggs.some(e=>e.id===failedClutch)&&AL.game.stats.hatched===failedHatches")
 runjs("AL.Shell.open('equipment','care');AL.UI.toast('Care action feedback remains visible inside this window.',true)")
 ck('Action errors remain visible and accessible above the modal backdrop',"(()=>{const n=document.querySelector('#primary-dialog .modal-feedback');return n?.getAttribute('role')==='status'&&n.textContent.includes('Care action feedback')&&n.getBoundingClientRect().height>0;})()")
 # Existing integrity and biological checks use the already-established test module.
 client.evaluate((root/'tests/economy_checks.js').read_text(encoding='utf8'))
 logic=client.evaluate('runEconomyChecks()');checks+=logic['results']
 runjs("AL.Shell.close(false);AL.Startup?.finish();AL.UI.close();AL.Store.close(false);AL.game.settings.speed=0;AL.UI.render();AL.renderer.zoom=1;AL.renderer.draw(AL.game,0)")
 shot('final-main')
 errors=[e for e in client.events if e.get('method')=='Runtime.exceptionThrown'];requests=[e['params']['request']['url'] for e in client.events if e.get('method')=='Network.requestWillBeSent' and e['params']['request']['url'].startswith(('http:','https:'))]
 checks.append({'name':'No JavaScript browser exceptions','pass':not errors,'errors':errors});checks.append({'name':'Runs file:// without remote requests','pass':not requests})
 report={'checks':checks,'passed':sum(c['pass'] for c in checks),'failed':sum(not c['pass'] for c in checks),'networkRequests':requests}
 (out/f'{name}-results.json').write_text(json.dumps(report,indent=2),encoding='utf8');print(json.dumps({'browser':name,'passed':report['passed'],'failed':report['failed'],'failures':[c for c in checks if not c['pass']]}),flush=True)
 return int(report['failed']>0)
